@Test(timeOut = ADC_TIMEOUT, groups = { "smoke" })
public void testADC() throws Exception {
    startCommunicatorThread();
    assertAgentActivation();
    Thread adcTestThread = new Thread(new Runnable() {

        @Override
        public void run() {
            String artifactFileName = "pca-live-" + UUID.randomUUID();
            File file = new File(APPLICATION_PATH + File.separator + artifactFileName);
            boolean fileCreated = false;
            boolean fileDeleted = false;
            boolean repoCloned = false;
            log.info("Running ADC Test thread...");
            // Send artifact updated event
            publishEvent(getArtifactUpdatedEventForPrivateRepo());
            log.info("Publishing artifact updated event for repo: " + getArtifactUpdatedEventForPrivateRepo().getRepoURL());
            List<String> outputLines = new ArrayList<>();
            while (!outputStream.isClosed() && !hasADCTestCompleted) {
                List<String> newLines = getNewLines(outputLines, outputStream.toString());
                if (newLines.size() > 0) {
                    for (String line : newLines) {
                        if (line.contains("Git clone executed")) {
                            log.info("Agent has completed git clone. Asserting the operation...");
                            assertRepoClone(getArtifactUpdatedEventForPrivateRepo());
                            repoCloned = true;
                        }
                        if (repoCloned && !fileCreated) {
                            try {
                                if (!file.createNewFile()) {
                                    throw new RuntimeException("Could not create [file] " + file.getAbsolutePath());
                                }
                                fileCreated = true;
                                continue;
                            } catch (IOException e) {
                                log.error("Could not create file", e);
                            }
                        }
                        if (fileCreated && line.contains("ArtifactUpdateTask end of iteration") && !fileDeleted) {
                            if (!file.delete()) {
                                throw new RuntimeException("Could not delete [file] " + file.getAbsolutePath());
                            }
                            fileDeleted = true;
                            continue;
                        }
                        // assert whether file deletion commit was pushed to remote repo
                        if (fileDeleted && line.contains("ArtifactUpdateTask end of iteration") && !hasADCTestCompleted) {
                            boolean fileExists = new File(file.getAbsolutePath()).exists();
                            assertFalse("Deleted file has not been pushed to remote repo", fileExists);
                            if (!fileExists) {
                                hasADCTestCompleted = true;
                            }
                        }
                    }
                }
                sleep(1000);
            }
        }
    });
    adcTestThread.start();
    while (!hasADCTestCompleted) {
        // wait until the instance activated event is received.
        sleep(1000);
    }
    log.info("ADC Test completed");
}

@Test(timeOut = STARTUP_TIMEOUT, description = "Test PCA initialization, activation, health stat publishing and " + "topology context update", groups = { "smoke" })
public void testPythonCartridgeAgent() {
    startCommunicatorThread();
    subscribeToThriftDatabridge();
    Thread startupTestThread = new Thread(new Runnable() {

        @Override
        public void run() {
            while (!eventReceiverInitiated) {
                sleep(2000);
            }
            List<String> outputLines = new ArrayList<String>();
            while (!outputStream.isClosed()) {
                List<String> newLines = getNewLines(outputLines, outputStream.toString());
                if (newLines.size() > 0) {
                    for (String line : newLines) {
                        if (line.contains("Subscribed to 'topology/#'")) {
                            sleep(2000);
                            // Send complete topology event
                            log.info("Publishing complete topology event...");
                            CompleteTopologyEvent completeTopologyEvent = new CompleteTopologyEvent(topology);
                            publishEvent(completeTopologyEvent);
                            log.info("Complete topology event published");
                            // Publish member initialized event
                            log.info("Publishing member initialized event...");
                            MemberInitializedEvent memberInitializedEvent = new MemberInitializedEvent(SERVICE_NAME, CLUSTER_ID, CLUSTER_INSTANCE_ID, MEMBER_ID, NETWORK_PARTITION_ID, PARTITION_ID, INSTANCE_ID);
                            publishEvent(memberInitializedEvent);
                            log.info("Member initialized event published");
                        }
                        if (line.contains("Published event to thrift stream")) {
                            startupTestCompleted = true;
                        }
                        // assert topology context update
                        if (line.contains("Topology context update test passed!")) {
                            topologyContextTestCompleted = true;
                        }
                    }
                }
                sleep(1000);
            }
        }
    });
    startupTestThread.start();
    instanceStatusEventReceiver.addEventListener(new InstanceActivatedEventListener() {

        @Override
        protected void onEvent(Event event) {
            log.info("Publishing complete topology with a new member...");
            Member newMember = new Member(SERVICE_NAME, CLUSTER_ID, "new-member", CLUSTER_INSTANCE_ID, NETWORK_PARTITION_ID, PARTITION_ID, LoadBalancingIPType.Private, System.currentTimeMillis());
            topology.getService(SERVICE_NAME).getCluster(CLUSTER_ID).addMember(newMember);
            CompleteTopologyEvent completeTopologyEvent = new CompleteTopologyEvent(topology);
            publishEvent(completeTopologyEvent);
            log.info("Complete topology event published with new member");
        }
    });
    while (!instanceStarted || !instanceActivated || !startupTestCompleted || !topologyContextTestCompleted || !thriftTestCompleted) {
        // wait until the instance activated event is received.
        // this will assert whether instance got activated within timeout period; no need for explicit assertions
        sleep(2000);
    }
}

@Test(timeOut = STARTUP_TIMEOUT, description = "Test PCA initialization, activation, health stat publishing in " + "CEP HA mode", groups = { "smoke" })
public void testPythonCartridgeAgent() {
    startCommunicatorThread();
    subscribeToThriftDatabridge();
    subscribeToSecondThriftDatabridge();
    Thread startupTestThread = new Thread(new Runnable() {

        @Override
        public void run() {
            while (!eventReceiverInitiated) {
                sleep(2000);
            }
            List<String> outputLines = new ArrayList<String>();
            while (!outputStream.isClosed()) {
                List<String> newLines = getNewLines(outputLines, outputStream.toString());
                if (newLines.size() > 0) {
                    for (String line : newLines) {
                        if (line.contains("Subscribed to 'topology/#'")) {
                            sleep(2000);
                            // Send complete topology event
                            log.info("Publishing complete topology event...");
                            CompleteTopologyEvent completeTopologyEvent = new CompleteTopologyEvent(topology);
                            publishEvent(completeTopologyEvent);
                            log.info("Complete topology event published");
                            // Publish member initialized event
                            log.info("Publishing member initialized event...");
                            MemberInitializedEvent memberInitializedEvent = new MemberInitializedEvent(SERVICE_NAME, CLUSTER_ID, CLUSTER_INSTANCE_ID, MEMBER_ID, NETWORK_PARTITION_ID, PARTITION_ID, INSTANCE_ID);
                            publishEvent(memberInitializedEvent);
                            log.info("Member initialized event published");
                        }
                        if (line.contains("Published event to thrift stream")) {
                            startupTestCompleted = true;
                        }
                        if (line.contains("Couldn't publish health statistics to CEP. Thrift Receiver offline.")) {
                            failDetected = true;
                        }
                    }
                }
                sleep(1000);
            }
        }
    });
    startupTestThread.start();
    instanceStatusEventReceiver.addEventListener(new InstanceActivatedEventListener() {

        @Override
        protected void onEvent(Event event) {
            log.info("Publishing complete topology with a new member...");
            Member newMember = new Member(SERVICE_NAME, CLUSTER_ID, "new-member", CLUSTER_INSTANCE_ID, NETWORK_PARTITION_ID, PARTITION_ID, LoadBalancingIPType.Private, System.currentTimeMillis());
            topology.getService(SERVICE_NAME).getCluster(CLUSTER_ID).addMember(newMember);
            CompleteTopologyEvent completeTopologyEvent = new CompleteTopologyEvent(topology);
            publishEvent(completeTopologyEvent);
            log.info("Complete topology event published with new member");
        }
    });
    while (!instanceStarted || !instanceActivated || !startupTestCompleted || !thriftTestCompletedinServerOne || !thriftTestCompletedinServerTwo) {
        // wait until the instance activated event is received.
        // this will assert whether instance got activated within timeout period; no need for explicit assertions
        sleep(2000);
    }
    thriftTestServer.stop();
    startupTestCompleted = false;
    thriftTestCompletedinServerTwo = false;
    while (!startupTestCompleted || !failDetected || !thriftTestCompletedinServerTwo) {
        // wait until PCA publishes health stats to second thrift server
        sleep(2000);
    }
    thriftTestCompletedinServerOne = false;
    try {
        thriftTestServer.start(cepPort);
        subscribeToThriftDatabridge();
    } catch (DataBridgeException e) {
        e.printStackTrace();
    }
    while (!thriftTestCompletedinServerOne) {
        // wait until PCA publishes health stats to started node
        sleep(2000);
    }
}

