    assertEquals(beanG1.getName(), "esb-php-group-application-bursting-test");
    boolean addedN1 = restClient.addEntity(RESOURCES_PATH + RestConstants.NETWORK_PARTITIONS_PATH + "/" + "network-partition-application-bursting-test-1.json", RestConstants.NETWORK_PARTITIONS, RestConstants.NETWORK_PARTITIONS_NAME);
    assertTrue(addedN1);
    boolean addedN2 = restClient.addEntity(RESOURCES_PATH + RestConstants.NETWORK_PARTITIONS_PATH + "/" + "network-partition-application-bursting-test-2.json", RestConstants.NETWORK_PARTITIONS, RestConstants.NETWORK_PARTITIONS_NAME);
    assertTrue(addedN2);
    boolean addedDep = restClient.addEntity(RESOURCES_PATH + RestConstants.DEPLOYMENT_POLICIES_PATH + "/" + "deployment-policy-application-bursting-test.json", RestConstants.DEPLOYMENT_POLICIES, RestConstants.DEPLOYMENT_POLICIES_NAME);
    assertTrue(addedDep);
    boolean added = restClient.addEntity(RESOURCES_PATH + RestConstants.APPLICATIONS_PATH + "/" + "app-bursting-single-cartriddge-group.json", RestConstants.APPLICATIONS, RestConstants.APPLICATIONS_NAME);
    assertTrue(added);
    ApplicationBean bean = (ApplicationBean) restClient.getEntity(RestConstants.APPLICATIONS, "application-bursting-test", ApplicationBean.class, RestConstants.APPLICATIONS_NAME);
    assertEquals(bean.getApplicationId(), "application-bursting-test");
    boolean addAppPolicy = restClient.addEntity(RESOURCES_PATH + RestConstants.APPLICATION_POLICIES_PATH + "/" + "application-policy-application-bursting-test.json", RestConstants.APPLICATION_POLICIES, RestConstants.APPLICATION_POLICIES_NAME);
    assertTrue(addAppPolicy);
    ApplicationPolicyBean policyBean = (ApplicationPolicyBean) restClient.getEntity(RestConstants.APPLICATION_POLICIES, "application-policy-application-bursting-test", ApplicationPolicyBean.class, RestConstants.APPLICATION_POLICIES_NAME);
    //deploy the application
    String resourcePath = RestConstants.APPLICATIONS + "/" + "application-bursting-test" + RestConstants.APPLICATIONS_DEPLOY + "/" + "application-policy-application-bursting-test";
    boolean deployed = restClient.deployEntity(resourcePath, RestConstants.APPLICATIONS_NAME);
    assertTrue(deployed);
    //Application active handling
    topologyHandler.assertApplicationStatus(bean.getApplicationId(), ApplicationStatus.Active);
    //Group active handling
    topologyHandler.assertGroupActivation(bean.getApplicationId());
    //Cluster active handling
    topologyHandler.assertClusterActivation(bean.getApplicationId());
    boolean removedGroup = restClient.removeEntity(RestConstants.CARTRIDGE_GROUPS, "esb-php-group-application-bursting-test", RestConstants.CARTRIDGE_GROUPS_NAME);
    assertFalse(removedGroup);
    boolean removedAuto = restClient.removeEntity(RestConstants.AUTOSCALING_POLICIES, autoscalingPolicyId, RestConstants.AUTOSCALING_POLICIES_NAME);
    assertFalse(removedAuto);
    boolean removedNet = restClient.removeEntity(RestConstants.NETWORK_PARTITIONS, "network-partition-application-bursting-test-1", RestConstants.NETWORK_PARTITIONS_NAME);
    //Trying to remove the used network partition
    assertFalse(removedNet);
    boolean removedDep = restClient.removeEntity(RestConstants.DEPLOYMENT_POLICIES, "deployment-policy-application-bursting-test", RestConstants.DEPLOYMENT_POLICIES_NAME);
    assertFalse(removedDep);
    //Un-deploying the application
    String resourcePathUndeploy = RestConstants.APPLICATIONS + "/" + "application-bursting-test" + RestConstants.APPLICATIONS_UNDEPLOY;
    boolean unDeployed = restClient.undeployEntity(resourcePathUndeploy, RestConstants.APPLICATIONS_NAME);
    assertTrue(unDeployed);
    boolean undeploy = topologyHandler.assertApplicationUndeploy("application-bursting-test");
