    assertEquals(String.format("[autoscaling-policy-id] %s RIF is not correct", policyId), updatedBean.getLoadThresholds().getRequestsInFlight().getThreshold(), 30.0, 0.0);
    assertEquals(String.format("[autoscaling-policy-id] %s Load is not correct", policyId), updatedBean.getLoadThresholds().getMemoryConsumption().getThreshold(), 40.0, 0.0);
    assertEquals(String.format("[autoscaling-policy-id] %s Memory is not correct", policyId), updatedBean.getLoadThresholds().getLoadAverage().getThreshold(), 20.0, 0.0);
